import React, { useEffect, useState } from 'react'
import TenantsTable from './TenantsTable'
import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import TenantFormModal from './TenantFormModal';
import propertiesApi from '../../../api/properties/propertiesApi';
import { Loading } from '../../../components';
import ViewContractPDFModal from './ViewContractPDFModal';

const columns = [

    { name: "First Name", uid: "first_name" },
    { name: "Last Name", uid: "last_name" },
    { name: "Gender", uid: "gender" },
    { name: "Date of Birth", uid: "date_of_birth" },
    { name: "Lease Start", uid: "lease_start" },
    { name: "Lease End", uid: "lease_end" },
    { name: "Property", uid: "property_title" },
    { name: "Property unit", uid: "property_unit_title" },
    { name: "Active", uid: "is_active" },
    { name: "Actions", uid: "actions" },
];


function TenantsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const navigate = useNavigate()
    const [tenant, setTenant] = useState()
    const [tenants, setTenants] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [openPDFModal, setopenPDFModal] = useState(false)

    const tenantsActionsApi = useApi(propertiesApi.propertiesAction)
    const [contractUrl, setcontractUrl] = useState()

    const getProperties = async () => {
        await tenantsActionsApi.request({
            "action": "GetEntityTenants"

        })
    }


    useEffect(() => {
        getProperties()
    }, [])


    const handleEditAction = (item) => {
      console.log("to edit ", item);
      setUpdated(false);
      setopenEditModal(true);
      setTenant(item);
      setmodalTitle(`${item.title}`);
    };

    const handleAddAction = () => {
      setUpdated(false);
      setopenEditModal(true);
      setmodalTitle("Add new tenant");
      setTenant(null);
    };
    const handleDetailsAction = (property) => {
      navigate(`/realty/properties/tenants/details`, {
        state: {
          property: property,
        },
      });
    };
    const handleDeleteAction = (property) => {
      navigate(`/realty/properties/tenants/delete/${property.id}`);
    };

    useEffect(() => {
      if (tenantsActionsApi.data && tenantsActionsApi.data.length) {
        setTenants(tenantsActionsApi.data);
      }

      console.log("tenantsActionsApi.data", tenantsActionsApi.data);
    }, [tenantsActionsApi.data]);

    useEffect(() => {
      getProperties();
    }, [updated]);

    //Filtering data
    useEffect(() => {
      setdata(tenants);
    }, [tenants]);

    const handleFilter = (e) => {
      const search_param = e;

      if (
        tenants &&
        tenants.length > 0 &&
        search_param &&
        search_param !== ""
      ) {
        setdata(
          tenants.filter((x) => x.title.toLowerCase().includes(search_param))
        );
      } else {
        setdata(tenants);
      }
    };

    const handleViewContract = (item) => {
      console.log("view contract", item);
      setopenPDFModal(true);
      setcontractUrl(item.contract)
    }

    return (
      <div>
      {openPDFModal && contractUrl&& <ViewContractPDFModal  openPDFModal={openPDFModal} setopenPDFModal={setopenPDFModal} contractUrl={contractUrl}/>}
        {openEditModal && (
          <TenantFormModal
            ismodalOpen={openEditModal}
            setisModalOpen={setopenEditModal}
            tenantToEdit={tenant}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        {tenantsActionsApi.loading ? (
          <Loading loading={tenantsActionsApi.loading} />
        ) : (
          <TenantsTable
            data={data}
            columns={columns}
            editAction={handleEditAction}
            detailsAction={handleDetailsAction}
            deleteAction={handleDeleteAction}
            addAction={handleAddAction}
            handleFilter={handleFilter}
            title={"Tenants"}
            handleViewContract={handleViewContract}
          />
        )}
      </div>
    );
}

export default TenantsList